#!/usr/bin/env python3
"""Write docs/macros.md from param/macros.yaml (the single source of truth). Run after editing macros:
python3 tools/gen_macro_docs.py            # a test (test_macro_library.py) fails when docs/macros.md is stale
"""
import json
import os
import sys

ROOT = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..')


def render(lib, whitelist):
    out = ['# Macro reference', '',
           'Generated by `tools/gen_macro_docs.py` from `src/framework_bringup/param/macros.yaml`; do not edit by hand.',
           f'{len(lib)} macros, {len(whitelist or [])} on the whitelist (the only ones the LLM/SLM may call; macros may call any macro).',
           '', 'A task spec calls one as `{"macro": "<name>", "args": {...}}`. `arg?` = optional (has a default).', '',
           '| Macro | Args | What it does | LLM may call |', '|---|---|---|---|']
    for name in sorted(lib):
        m = lib[name]
        args = ', '.join(p if (d or {}).get('required', 'default' not in (d or {})) else f'{p}?' for p, d in m['params'].items())
        ex = f' Example: `{json.dumps(m["example_args"])}`.' if m['example_args'] else ''
        out.append(f'| `{name}` | {args or "-"} | {m["description"]}.{ex} | {"yes" if whitelist is None or name in whitelist else "no"} |'
                   .replace('..', '.'))
    return '\n'.join(out) + '\n'


def main():
    sys.path.insert(0, os.path.join(ROOT, 'src', 'bt_common'))
    from bt_common.macros import load_macros, load_whitelist
    path = os.path.join(ROOT, 'src', 'framework_bringup', 'param', 'macros.yaml')
    text = render(load_macros(path), load_whitelist(path))
    with open(os.path.join(ROOT, 'docs', 'macros.md'), 'w') as f:
        f.write(text)
    print(f'docs/macros.md written ({text.count(chr(10))} lines)')


if __name__ == '__main__':
    main()
